={{ (function() {
  const data = $json.body?.data || $json.data || {};
  const msgType = String(data.messageType || '');
  if (msgType === 'reactionMessage') return false;

  const key = data.key || {};
  const fromMe = Boolean(key.fromMe);
  const remoteJid = String(key.remoteJid || '');
  const phone = remoteJid.replace(/\D/g, '');
  const id = String(key.id || '');
  const source = String(data.source || '').toLowerCase();
  const isBotApi = id.startsWith('3EB0') || id.startsWith('BAE5') || source === 'web' || source === 'api';

  // 1. Quando a atendente humana ou a Michele mandar mensagem no WhatsApp para um cliente:
  if (fromMe && !isBotApi) {
    const isMicheleSelf = phone.endsWith('997349076') || phone.endsWith('97349076');
    // Se a Michele estiver conversando com ela mesma (chat Você para testar):
    if (isMicheleSelf) {
      return (source === 'android' || source === 'ios' || !isBotApi);
    }
    // Intervenção humana no circuito da conversa: pausa a Maya por 2 minutos para este cliente!
    const sd = $getWorkflowStaticData('global');
    if (!sd.pausaHumana) sd.pausaHumana = {};
    sd.pausaHumana[phone] = Date.now() + (2 * 60 * 1000);
    return false;
  }

  // Se for mensagem enviada pela própria API da Maya: bloqueia para não gerar loop
  if (fromMe && isBotApi) return false;

  // 2. Quando o cliente enviar mensagem (fromMe === false):
  // Verifica se a conversa está no período de pausa humana automática de 2 minutos:
  const sd = $getWorkflowStaticData('global');
  const pausaAte = sd.pausaHumana?.[phone] || 0;
  if (Date.now() < pausaAte) {
    // Atendente humana assumiu nos últimos 2 minutos -> Maya permanece pausada em silêncio
    return false;
  }

  // Passou de 2 minutos sem novas mensagens da atendente -> Maya assume o atendimento automaticamente!
  return true;
})() }}

