  (function() {
    const raw = String('{termo_busca}' || $('Coleta').first()?.json?.telefone || '').replace(/[#\s]/g, '');
    const isNum = /^\d+$/.test(raw);
    const phone = String($('Coleta').first()?.json?.telefone || '').replace(/\D/g, '');
    let filter = '';
    if (isNum && raw.length <= 6) {
      filter = 'or=(id.eq.' + raw + ',customer_phone.ilike.*' + phone + '*)';
    } else if (raw.length > 6 && !isNaN(raw)) {
      filter = 'customer_phone.ilike.*' + raw + '*';
    } else if (raw) {
      filter = 'or=(tracking_code.ilike.*' + raw + '*,customer_phone.ilike.*' + phone + '*)';
    } else {
      filter = 'customer_phone.ilike.*' + phone + '*';
    }
    return 'https://wpxujeieopgoxodttjqp.supabase.co/rest/v1/orders?' + filter + '&select=id,status,customer_name,order_type,total_amount,items,created_at,tracking_code,delivery_address,delivery_zone&order=created_at.desc&limit=1';
  })()
}}

