// ================= CONFIGURAÇÃO DOS SÓCIOS (MAIS AÇAÍ SJP) =================
const item = $input.first().json;
const phone = String($('Coleta').first()?.json?.telefone || '').replace(/\D/g, '');

const DONOS_JUNIOR = ['5541996560080', '41996560080', '996560080', '554196560080', '4196560080', '96560080'];
const DONOS_MICHELE = ['5541997349076', '41997349076', '997349076', '554197349076', '4197349076', '97349076'];
const TODOS_DONOS = [...DONOS_JUNIOR, ...DONOS_MICHELE];

if (!TODOS_DONOS.some(d => phone.endsWith(d) || d.endsWith(phone))) {
  return [{ json: { ...item, rota: 'cliente' } }];
}

const isJunior = DONOS_JUNIOR.some(d => phone.endsWith(d) || d.endsWith(phone));
const nomeDono = isJunior ? 'Junior' : 'Michele';

const sd = $getWorkflowStaticData('global');
const agoraSp = DateTime.now().setZone('America/Sao_Paulo');
const hoje = agoraSp.toFormat('yyyyMMdd');
const chaveModo = 'modoDono_' + (isJunior ? 'junior' : 'michele');
let modo = (sd[chaveModo] && sd[chaveModo].dia === hoje) ? sd[chaveModo].modo : 'assistente';

let texto = String(item.text || '');
const re = /#?\bmodo\s+(cliente|assistente|gestor|dono|dona|socio|sócio)\b[.!\s]*/i;
const m = texto.match(re);
let aviso = '';
if (m) {
  modo = m[1].toLowerCase() === 'cliente' ? 'cliente' : 'assistente';
  sd[chaveModo] = { modo, dia: hoje };
  texto = texto.replace(re, '').trim();
  if (!texto) {
    aviso = modo === 'cliente'
      ? '👤 Modo cliente ativado. A partir de agora a Maya te atende como cliente normal da açaiteria. Para voltar, envie: *modo assistente*'
      : '👑 Modo assistente ativado, ' + nomeDono + '! Estou pronta para te passar relatórios de vendas, copos mais vendidos, faturamento, bairros com mais entregas ou status da loja. Para testar como cliente, envie: *modo cliente*';
  }
}

const base = { ...item, text: texto, nomeDono };
if (aviso) return [{ json: { ...base, rota: 'aviso', resposta: aviso } }];
return [{ json: { ...base, rota: modo } }];

const j = $input.first().json;
const txt = String(j.output ?? j.resposta ?? '').replace(/\[\s*SIL[EÊ]NCIO\s*\]/gi, '').trim();
const partes = txt.split('|||').map(s => s.trim()).filter(Boolean);
return partes.map(p => ({ json: { item: p } }));

const inp = $input.first()?.json || {};
const agrupa = String($('AGRUPA MENSAGENS').first()?.json?.concatenated_content || '').replace(/^=+/, '').trim();
const coleta = String($('Coleta').first()?.json?.mensagem || '').trim();
const raw = String($('Recebe mensagem').first()?.json?.body?.data?.message?.conversation || $('Recebe mensagem').first()?.json?.body?.data?.message?.extendedTextMessage?.text || '').trim();
const txt = String(inp.text || agrupa || (coleta !== '[Arquivo/Midia]' ? coleta : '') || raw || 'Olá').trim();
return [{ json: { text: txt || 'Olá' } }];

